    "Content": "<h4>[resource_displayname[TotalCountOfEarlyPaidInvoices]]</h4>
<div name="chart" class = "flex-column"></div>
<style>
   .component[name=TotalCountOfEarlyPaidInvoices] { max-height: 340px; max-width: 550px; flex: 1 1 550px; }
   [name=chart] {flex: 1; }
</style>",
    "Script": "TotalCountOfEarlyPaidInvoices = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=TotalCountOfEarlyPaidInvoices]");
        var data = await TotalCountOfEarlyPaidInvoices.getData(app);
		TotalCountOfEarlyPaidInvoices.initChart(container, data, app.Config.B2B.Currencies);
	},

    getData: async function(app) {
		var data = [];
		for(let i = 0; i < 12; i++) {
			let date = new Date();
			date.setMonth(date.getMonth() - 12);
			const offset = date.getTimezoneOffset()
			const firstDay = new Date((new Date(date.getFullYear(), date.getMonth() + i, 1)).getTime() - (offset*60*1000)).toISOString().split("T")[0];
			const lastDay = new Date((new Date(date.getFullYear(), date.getMonth() + (i + 1), 0)).getTime() - (offset*60*1000)).toISOString().split("T")[0];
			data.push(api.get(`B2B/Invoice/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$apply=filter(TaxPoint ge ${firstDay} and TaxPoint le ${lastDay} and (FundingState eq 'FundingAccepted' or FundingState eq 'Paid'))/groupby((CurrencyId), aggregate(Id with countdistinct as Total))`).then((chartData) => {
				if(chartData.length > 0) {
					for(let c in app.Config.B2B.Currencies) {
						var matchingCurrency = chartData.filter(r => r.CurrencyId === app.Config.B2B.Currencies[c]);
						if(matchingCurrency.length > 0) {
							return matchingCurrency.map(r => { r.CalendarMonth = firstDay.split("-")[0] + "-" + firstDay.split("-")[1]; return r; });
						} else {
							return { CalendarMonth:  firstDay.split("-")[0] + "-" + firstDay.split("-")[1], Total: 0, CurrencyId: app.Config.B2B.Currencies[c] };
						}
					}
				} else {
					for(let c in app.Config.B2B.Currencies) {
						return { CalendarMonth:  firstDay.split("-")[0] + "-" + firstDay.split("-")[1], Total: 0, CurrencyId: app.Config.B2B.Currencies[c] };
					}
				}
			}));
		}
        return (await Promise.all(data)).flat();
    },

	initChart: function (container, data, currencies) {
		var categories = data.map(i => i.CalendarMonth).filter((value, index, self) => self.indexOf(value) === index);
		console.log({ component: "TotalCountOfEarlyPaidInvoices", data: data });
		var args = {
			showLegend: true,
			valueTemplate: "#: kendo.toString(value, type.numberFormat)#",
			tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.numberFormat) #",
			series: currencies.map(cur => ({
				name: "[resource_displayname[Count]] (" + cur + ")",
				data: categories.map(c => data.filter(r => r.CalendarMonth === c && r.CurrencyId === cur).map(i => i.Total))
			})),
			categories: categories,
			max: data.map(i => i.Total).sort((a, b) => b - a)[0],
			type: "column"
		};
		return (new Chart($("[name=chart]", container), args)).init();
	}
}",
